const fmt = formatDateTime;
const clean = (v, max=160) => String(v || '').trim().slice(0,max);
const asDataUrl = file => new Promise((resolve,reject) => { const reader=new FileReader(); reader.onerror=()=>reject(new Error('Photo could not be read.')); reader.onload=()=>resolve(reader.result); reader.readAsDataURL(file); });
const withTimeout = (promise, message, ms=12000) => Promise.race([promise, new Promise((_,reject)=>setTimeout(()=>reject(new Error(message)),ms))]);
const cloudinaryName = import.meta.env.VITE_CLOUDINARY_CLOUD_NAME;
const cloudinaryPreset = import.meta.env.VITE_CLOUDINARY_UPLOAD_PRESET;
async function uploadStudentPhoto(file) {
  if (!cloudinaryName || !cloudinaryPreset) return asDataUrl(file);
  try {
    const body = new FormData();
    body.append('file', file); body.append('upload_preset', cloudinaryPreset); body.append('folder', 'campuspass/profilePhotos');
    const response = await fetch(`https://api.cloudinary.com/v1_1/${cloudinaryName}/image/upload`, { method:'POST', body });
    const result = await response.json();
    if (!response.ok || !result.secure_url) throw new Error('Cloudinary upload failed.');
    return result.secure_url;
  } catch { return asDataUrl(file); }
}
async function uploadCloudinaryFile(file, folder='campuspass/permissionLetters') {
  if (!cloudinaryName || !cloudinaryPreset) throw new Error('Add the Cloudinary unsigned upload preset to .env before uploading files.');
  const body=new FormData(); body.append('file',file); body.append('upload_preset',cloudinaryPreset); body.append('folder',folder);
  const type=file.type==='application/pdf'?'raw':'image';
  const response=await fetch(`https://api.cloudinary.com/v1_1/${cloudinaryName}/${type}/upload`,{method:'POST',body}); const result=await response.json();
  if(!response.ok||!result.secure_url)throw new Error(result.error?.message||'Cloudinary file upload failed.'); return result.secure_url;
}
function DocumentPreview({url,name}){if(!url)return <div className="attachment missing"><small>Supporting document</small><b>No document attached</b></div>;const image=/\.(png|jpe?g|webp|gif)(\?|$)/i.test(url);return <div className="attachment"><div><small>Supporting document</small><b>{name||'Student attachment'}</b></div>{image&&<a href={url} target="_blank" rel="noreferrer"><img src={url} alt="Student supporting document"/></a>}<a className="secondary attachment-link" href={url} target="_blank" rel="noreferrer">Open / verify document</a></div>}
const friendlyError = error => {
  if (error?.code === 'permission-denied') return 'You do not have permission for this action. Ask an administrator to verify your role.';
  return error?.message || 'Something went wrong. Please try again.';
};

export function CampusPassApp() {
  const [profile,setProfile]=useState(null), [demo,setDemo]=useState(false), [notice,setNotice]=useState(''), [accessError,setAccessError]=useState(''), [authLoading,setAuthLoading]=useState(firebaseReady), [loggingOut,setLoggingOut]=useState(false);
  useEffect(()=>{if(!notice)return;const timer=setTimeout(()=>setNotice(''),3500);return()=>clearTimeout(timer)},[notice]);
  useEffect(()=>{if(!auth)return;let stopProfile;const stopAuth=onAuthStateChanged(auth,current=>{stopProfile?.();setProfile(null);setAuthLoading(!!current);if(!current){setAuthLoading(false);return;}stopProfile=onSnapshot(doc(db,'users',current.uid),snap=>{setAuthLoading(false);if(!snap.exists()){setAccessError('Your account exists, but its Firestore profile is missing. Complete your access request.');setProfile(null);return;}setAccessError('');setProfile({uid:current.uid,...snap.data()});},error=>{setAuthLoading(false);setAccessError(friendlyError(error));setProfile(null)});});return()=>{stopAuth();stopProfile?.()};},[]);
  const active=profile;
  const session=usePortalSession(active?.uid,!demo&&active?.active===true&&!active.disabled&&!active.deletionPending&&!loggingOut);
  useEffect(()=>{if(!session.error)return;setAccessError(session.error);signOut(auth).catch(()=>{});setProfile(null);},[session.error]);
  async function logout(){if(loggingOut)return;setLoggingOut(true);try{if(!demo){await withTimeout(releasePortalSession(),'Session release timed out.',4000).catch(()=>{});await signOut(auth);}setProfile(null);setDemo(false);setNotice('');setAccessError('');}catch(error){setNotice(friendlyError(error));}finally{setLoggingOut(false)}}
  if(authLoading)return <main className="session-loading" role="status">Loading your account…</main>;
  if(!active)return <Login missingProfile={accessError.startsWith('Your account exists')} externalError={accessError} onDemo={role=>{setDemo(true);setProfile({...demoUser,role,active:true});}} onSignedIn={()=>{setAccessError('');setDemo(false)}}/>;
  if(!demo&&(active.active!==true||active.disabled||active.deletionPending))return <PendingAccess user={active} logout={logout}/>;
  if(!demo&&!session.ready)return <main className="session-loading" role="status"><p>{session.error||'Verifying your session…'}</p><button className="secondary" onClick={logout}>Back to sign in</button></main>;
  return <><Portal key={active.uid+active.role} user={active} demo={demo} notify={setNotice} logout={logout}/>{notice&&<div className="toast" onClick={()=>setNotice('')}>{notice}</div>}</>;
}
function PendingAccess({user,logout}){const blocked=['REJECTED','REMOVED'].includes(user.approvalStatus)||user.deleted||user.disabled||user.deletionPending;return <main className="login-shell"><section className="brand-pane"><CollegeLogo/><h1>{blocked?'Portal access unavailable.':'Account review in progress.'}</h1><p>{blocked?'Contact the campus administrator about your access.':'Your CampusPass profile is waiting for an administrator’s approval.'}</p></section><section className="login-card"><CollegeLogo/><div className="signin-copy"><p className="eyebrow">{blocked?'ACCESS UNAVAILABLE':'ACCESS PENDING'}</p><h2>{blocked?'Your account cannot access the portal':'Your registration was received'}</h2><p>{blocked?'Your account is disabled, rejected, or being deleted. Contact your campus administrator for help.':`Your requested ${user.requestedRole||'Student'} access is awaiting verification. You can use the portal once an administrator approves your account.`}</p></div><button className="primary full" onClick={logout}>Back to sign in</button></section></main>}
function CollegeLogo({compact=false}){return <div className={'college-logo '+(compact?'compact':'')}><img src="/logo-swce.png" alt="Study World College"/><span>CampusPass</span></div>}
function Avatar({user}){return <div className="avatar">{user.photoUrl?<img src={user.photoUrl} alt="Profile"/>:user.displayName?.slice(0,1)||'U'}</div>}

function Login({onDemo,onSignedIn,externalError,missingProfile=false}) {
  const [email,setEmail]=useState(''),[password,setPassword]=useState(''),[register,setRegister]=useState(false),[error,setError]=useState(''),[busy,setBusy]=useState(false),[resetMessage,setResetMessage]=useState('');
  async function resetPassword(){if(!email.trim())return setError('Enter your email first.');if(!firebaseReady)return setResetMessage('Password reset is available when Firebase is connected.');setBusy(true);setError('');try{await sendPasswordResetEmail(auth,email.trim());setResetMessage('If this email has an account, a password reset link has been sent.');}catch(e){setError(friendlyError(e))}finally{setBusy(false)}}
  async function submit(e){e.preventDefault();if(!firebaseReady)return onDemo(ROLES.STUDENT);setBusy(true);setError('');try{await signInWithEmailAndPassword(auth,email.trim(),password);onSignedIn();}catch{setError('Email or password is incorrect.');}finally{setBusy(false)}}
  return <main className="login-shell"><section className="brand-pane"><CollegeLogo/><p className="eyebrow">STUDY WORLD COLLEGES</p><h1>Outpass management,<br/><em>made accountable.</em></h1><p>One connected workspace for students, approvers, hostel teams, and security.</p><div className="security-note"><ShieldCheck size={20}/>Controlled approvals · Verified gate movement</div></section><section className="login-card"><CollegeLogo/>{register?<RegisterAccount back={()=>setRegister(false)} onSignedIn={onSignedIn}/>:<><div className="signin-copy"><p className="eyebrow">SECURE ACCESS</p><h2>Sign in to CampusPass</h2><p>Use your approved college account.</p></div><form onSubmit={submit}><label>Student / staff email<input type="email" autoComplete="email" value={email} onChange={e=>setEmail(e.target.value)} required/></label><PasswordField label="Password" value={password} onChange={setPassword} autoComplete="current-password"/>{(error||externalError)&&<div className="error" role="alert">{error||externalError}</div>}<button className="primary full" disabled={busy}>{busy?'Signing in…':firebaseReady?'Sign in securely':'Open student preview'}</button></form>{resetMessage&&<p className="pending-notice" role="status">{resetMessage}</p>}<button className="account-link" disabled={busy} onClick={resetPassword}>Forgot password?</button><button className="account-link" onClick={()=>setRegister(true)}>{missingProfile?'Complete your access request':'Create your CampusPass account'}</button></>}</section></main>;
}
function PasswordField({label,value,onChange,autoComplete='new-password',minLength}){
  const [shown,setShown]=useState(false);
  return <label>{label}<span className="password-field"><input type={shown?'text':'password'} value={value} onChange={e=>onChange(e.target.value)} autoComplete={autoComplete} minLength={minLength} required/><button type="button" onClick={()=>setShown(x=>!x)} aria-label={shown?'Hide password':'Show password'} aria-pressed={shown}>{shown?<EyeOff size={18}/>:<Eye size={18}/>}</button></span></label>;
}

function RegisterAccount({back,onSignedIn}) {
  const existingUser=auth?.currentUser||null;
  const [form,setForm]=useState({displayName:existingUser?.displayName||'',registerNumber:'',institution:'',department:'',year:'',gender:'',section:'',studentPhone:'',hostel:'',parentPhone:'',phone:'',position:'',requestedRole:ROLES.STUDENT,email:existingUser?.email||'',password:''}),[photo,setPhoto]=useState(null),[error,setError]=useState(''),[busy,setBusy]=useState(false);
  const set=(k,v)=>setForm(x=>({...x,[k]:v}));
  async function submit(e){
    e.preventDefault();if(!firebaseReady)return setError('Add Firebase configuration before registering.');
    const invalid=profileError(form,form.requestedRole);if(invalid)return setError(invalid);
    if(!photo)return setError('Choose a profile photo.');
    if(!photo.type.startsWith('image/')||photo.size>350*1024)return setError('Choose a JPG, PNG, or WebP photo smaller than 350 KB.');
    const registerNumber=clean(form.registerNumber,40).toUpperCase();if(!/^[A-Z0-9_-]+$/.test(registerNumber))return setError('Use letters, numbers, hyphens, or underscores for your ID.');
    setBusy(true);setError('');let created;let createdNew=false;
    try{
      if(existingUser&&existingUser.email?.toLowerCase()===form.email.trim().toLowerCase())created=existingUser;
      else{const credential=await withTimeout(createUserWithEmailAndPassword(auth,form.email.trim(),form.password),'Sign-up timed out. Check your connection and retry.');created=credential.user;createdNew=true;}
      const photoUrl=await uploadStudentPhoto(photo);await updateProfile(created,{displayName:clean(form.displayName)});
      const profile={displayName:clean(form.displayName),email:clean(form.email).toLowerCase(),registerNumber,...profileForRole(form,form.requestedRole),photoUrl,role:ROLES.STUDENT,requestedRole:form.requestedRole,active:false,approvalStatus:'PENDING',createdAt:serverTimestamp()};
      const batch=writeBatch(db);batch.set(doc(db,'users',created.uid),profile);
      if(form.requestedRole===ROLES.STUDENT)batch.set(doc(db,'students',created.uid),{...profile,userId:created.uid});
      batch.set(doc(db,'registerNumbers',registerNumber),{uid:created.uid,createdAt:serverTimestamp()});
      await withTimeout(batch.commit(),'Profile submission timed out. Check your connection and retry.');await signOut(auth);onSignedIn();
    }catch(err){if(createdNew&&created)await deleteUser(created).catch(()=>{});setError(err.code==='auth/email-already-in-use'?'An account already exists for this email. Sign in, then complete your access request.':err.code==='permission-denied'?'This register number / staff ID is already registered, or your profile is invalid.':friendlyError(err));}finally{setBusy(false)}
  }
  return <><div className="signin-copy"><p className="eyebrow">ACCOUNT REGISTRATION</p><h2>{existingUser?'Complete your access request':'Request portal access'}</h2><p>Select your role and complete every field shown. An Admin verifies your account.</p></div><form onSubmit={submit} className="registration-form"><div className="register-grid"><label>Full name<input value={form.displayName} onChange={e=>set('displayName',e.target.value)} required/></label><label>Profile photo<input type="file" accept="image/png,image/jpeg,image/webp" onChange={e=>setPhoto(e.target.files?.[0])} required/><small>JPG, PNG, or WebP · max 350 KB</small></label><label>Requested portal role<select value={form.requestedRole} onChange={e=>set('requestedRole',e.target.value)} required>{Object.values(ROLES).map(x=><option key={x}>{x}</option>)}</select></label><label>{form.requestedRole===ROLES.STUDENT?'Register number':'Staff ID'}<input value={form.registerNumber} onChange={e=>set('registerNumber',e.target.value)} required/></label><ProfileFields form={form} set={set} role={form.requestedRole}/><label>{form.requestedRole===ROLES.STUDENT?'Student email':'Staff email'}<input type="email" value={form.email} onChange={e=>set('email',e.target.value)} readOnly={!!existingUser} required/></label>{!existingUser&&<PasswordField label="Create password" minLength={8} value={form.password} onChange={v=>set('password',v)}/>}</div>{error&&<div className="error" role="alert">{error}</div>}<button className="primary full" disabled={busy}>{busy?'Submitting…':'Submit access request'}</button></form><button className="account-link" onClick={back}>Back to sign in</button></>;
}

