      const record={studentId:user.uid,studentName:user.displayName,registerNumber:user.registerNumber,institution:user.institution,department:user.department,year:Number(user.year),gender:user.gender||'',section:user.section||'',photoUrl:user.photoUrl||'',studentPhone:profileForRole(form,ROLES.STUDENT).studentPhone,parentPhone:profileForRole(form,ROLES.STUDENT).parentPhone,reason:clean(form.reason,600),category:form.category,studentType:studentTypeOf(user),permissionPolicy:'FULL_APPROVAL',responsibilityAccepted:true,outAt:out.toISOString(),returnAt:back.toISOString(),outAtTimestamp:Timestamp.fromDate(out),returnAtTimestamp:Timestamp.fromDate(back),permissionLetterUrl,permissionLetterName:file?.name||'',status:'PENDING_ADVISOR',approvals:[],createdAt:demo?new Date():serverTimestamp(),updatedAt:demo?new Date():serverTimestamp()};
